Which similarity test proves that these two right-angled triangles are similar?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.85]
\coordinate (C) at (0,0);
\coordinate (B) at (0.7,0);
\coordinate (A) at (0,2.4);
\draw (C) -- (B) node[midway,below,font=\small] {$7$};
\draw (C) -- (A);
\draw (A) -- (B) node[midway,above right,font=\small] {$25$};
\coordinate (ca) at ($(C)!0.24cm!(B)$);
\coordinate (cb) at ($(C)!0.24cm!(A)$);
\draw (ca) -- ($(ca)+(cb)-(C)$) -- (cb);
\coordinate (C2) at (3.4,0);
\coordinate (B2) at (4.52,0);
\coordinate (A2) at (3.4,3.84);
\draw (C2) -- (B2) node[midway,below,font=\small] {$14$};
\draw (C2) -- (A2);
\draw (A2) -- (B2) node[midway,above right,font=\small] {$50$};
\coordinate (cc) at ($(C2)!0.24cm!(B2)$);
\coordinate (cd) at ($(C2)!0.24cm!(A2)$);
\draw (cc) -- ($(cc)+(cd)-(C2)$) -- (cd);
\end{tikzpicture}
[/tikz]

