Two of these three triangles are similar.
Which pair?
[tikz]
\begin{tikzpicture}[every node/.style={font=\large},scale=0.78]
\coordinate (A) at (0,0);
\coordinate (B) at (2.5,0);
\coordinate (C) at (1.684,1.413);
\draw (A) -- (B) -- (C) -- cycle;
\pic[draw,"$40^{\circ}$",angle radius=0.55cm,angle eccentricity=1.9,font=\small] {angle=B--A--C};
\pic[draw,"$60^{\circ}$",angle radius=0.4cm,angle eccentricity=2.2,font=\small] {angle=C--B--A};
\node[below,font=\small] at (1.25,-0.45) {$\Delta 1$};
\coordinate (D) at (3.3,0);
\coordinate (E) at (5.8,0);
\coordinate (F) at (4.43,1.957);
\draw (D) -- (E) -- (F) -- cycle;
\pic[draw,"$60^{\circ}$",angle radius=0.42cm,angle eccentricity=2.1,font=\small] {angle=E--D--F};
\pic[draw,"$55^{\circ}$",angle radius=0.45cm,angle eccentricity=2.1,font=\small] {angle=F--E--D};
\node[below,font=\small] at (4.55,-0.45) {$\Delta 2$};
\coordinate (G) at (6.6,0);
\coordinate (H) at (9.5,0);
\coordinate (I) at (7.546,1.639);
\draw (G) -- (H) -- (I) -- cycle;
\pic[draw,"$60^{\circ}$",angle radius=0.42cm,angle eccentricity=2.1,font=\small] {angle=H--G--I};
\pic[draw,"$40^{\circ}$",angle radius=0.55cm,angle eccentricity=1.9,font=\small] {angle=I--H--G};
\node[below,font=\small] at (8.05,-0.45) {$\Delta 3$};
\end{tikzpicture}
[/tikz]
